    private const JOBS_PER_CATEGORY = 10;

    public function run(): void
    {
        $this->ensureEmployers();

        foreach ($this->jobs() as $categoryName => $jobs) {
            $category = Category::where('name', $categoryName)->first();
            if (! $category) {
                $this->command?->warn("Category not found: {$categoryName}");
                continue;
            }

            $existing = JobListing::where('category_id', $category->id)->count();
            $needed = max(0, self::JOBS_PER_CATEGORY - $existing);

            $inserted = 0;
            foreach ($jobs as $job) {
                if ($inserted >= $needed) {
                    break;
                }

                if (JobListing::where('category_id', $category->id)->where('title', $job['title'])->exists()) {
                    continue;
                }

                $employer = Employer::where('company_name', $job['company'])->first();
                if (! $employer) {
                    $this->command?->warn("Employer not found: {$job['company']} for {$job['title']}");
                    continue;
                }

                $createdAt = now()->subDays($job['cr_days']);

                JobListing::create([
                    'employer_id' => $employer->id,
                    'category_id' => $category->id,
                    'title' => $job['title'],
                    'description' => $job['desc'],
                    'responsibilities' => $job['resp'],
                    'requirements' => $job['req'],
                    'benefits' => $job['ben'],
                    'skills_required' => $job['skills'],
                    'experience_level' => $job['exp'],
                    'salary_min' => $job['sal'][0],
                    'salary_max' => $job['sal'][1],
                    'salary_type' => $job['stype'],
                    'employment_type' => $job['etype'],
                    'location' => $job['loc'],
                    'workplace_type' => $job['wtype'],
                    'application_deadline' => now()->addDays($job['dl_days'])->format('Y-m-d'),
                    'is_featured' => $job['featured'],
                    'is_active' => true,
                    'status' => 'approved',
                    'vacancy_count' => $job['vac'],
                    'created_at' => $createdAt,
                    'updated_at' => $createdAt,
                ]);

                $inserted++;
            }

            $total = JobListing::where('category_id', $category->id)->count();
            $this->command?->info("Category [{$categoryName}]: {$existing} existing + {$inserted} added = {$total} total");
        }
    }

