    private function job(
        string $title,
        string $company,
        string $exp,
        array $sal,
        string $stype,
        string $etype,
        string $wtype,
        string $loc,
        int $vac,
        int $crDays,
        int $dlDays,
        bool $featured,
        string $desc,
        string $resp,
        string $req,
        string $ben,
        string $skills,
    ): array {
        return [
            'title' => $title,
            'company' => $company,
            'exp' => $exp,
            'sal' => $sal,
            'stype' => $stype,
            'etype' => $etype,
            'wtype' => $wtype,
            'loc' => $loc,
            'vac' => $vac,
            'cr_days' => $crDays,
            'dl_days' => $dlDays,
            'featured' => $featured,
            'desc' => $desc,
            'resp' => $resp,
            'req' => $req,
            'ben' => $ben,
            'skills' => $skills,
        ];
    }
}
